<?php require '../config/bootstrap.php';auth();verify_token();$id=(int)($_POST['id']??0);try{$s=$pdo->prepare('SELECT * FROM produk WHERE id=? AND user_id=?');$s->execute([$id,me()['id']]);$old=$s->fetch();if(!$old)throw new Exception('Produk tidak ditemukan');$n=trim($_POST['nama_produk']??'');$d=trim($_POST['deskripsi_produk']??'');$st=$_POST['status_produk']??'';if(!$n||!$d||!in_array($st,['ready_stock','pre_order','sold_out'],true))throw new Exception('Data tidak valid');$img=upload_img('gambar_produk','products')??$old['gambar_produk'];$pdo->prepare('UPDATE produk SET nama_produk=?,deskripsi_produk=?,gambar_produk=?,status_produk=?,whatsapp=? WHERE id=? AND user_id=?')->execute([$n,$d,$img,$st,trim($_POST['whatsapp']??''),$id,me()['id']]);if($img!==$old['gambar_produk'])del_img($old['gambar_produk']);flash('Produk diperbarui');}catch(Throwable $e){flash($e instanceof PDOException?'Gagal update database':$e->getMessage(),'error');}header('Location: ../my-products.php');exit;